-- Phase 1 migration 0005: attachments + backups
-- R2 objects are client-encrypted; no plaintext filename/keys/mime in any column.
CREATE TABLE attachments (
  attachment_id  TEXT PRIMARY KEY,
  sender_dev_id  TEXT NOT NULL REFERENCES devices(device_id),
  r2_key         TEXT NOT NULL UNIQUE,
  encrypted_size INTEGER NOT NULL CHECK (encrypted_size > 0),
  state          TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','ready')),
  server_recv_at INTEGER NOT NULL,
  expires_at     INTEGER NOT NULL
);
CREATE INDEX idx_att_expiry ON attachments(expires_at);

CREATE TABLE attachment_delivery (
  attachment_id TEXT NOT NULL REFERENCES attachments(attachment_id),
  device_id     TEXT NOT NULL REFERENCES devices(device_id),
  delivered_at  INTEGER,
  acked_at      INTEGER,
  PRIMARY KEY (attachment_id, device_id)
);
CREATE INDEX idx_att_delivery_device ON attachment_delivery(device_id);

CREATE TABLE backups (
  backup_id      TEXT PRIMARY KEY,
  account_id     TEXT NOT NULL REFERENCES accounts(account_id),
  r2_key         TEXT NOT NULL UNIQUE,
  encrypted_size INTEGER NOT NULL CHECK (encrypted_size > 0),
  backup_version INTEGER NOT NULL CHECK (backup_version > 0),
  created_at     INTEGER NOT NULL,
  expires_at     INTEGER NOT NULL
);
CREATE INDEX idx_backups_account ON backups(account_id, created_at);

import fs from "node:fs";
import { defineWorkersConfig } from "@cloudflare/vitest-pool-workers/config";

// The Tink→WebCrypto fixture is generated at runtime by the Android instrumented
// test (real Ed25519 signing on an emulator) and exported via logcat. It is
// optional here: when absent (pure backend CI), the interop spec is skipped and
// only migration/auth/token tests run against local miniflare D1.
const fixturePath = new URL("./tink-fixture.json", import.meta.url);
let fixture: unknown = null;
if (fs.existsSync(fixturePath)) {
  fixture = JSON.parse(fs.readFileSync(fixturePath, "utf8"));
}

// Migration files are read on the Node side (fs is unavailable inside workerd)
// and injected as a binding so the migration spec applies exactly what
// `wrangler d1 migrations apply` would apply, in order.
const migrationsDir = new URL("./migrations", import.meta.url);
const migrations = fs
  .readdirSync(migrationsDir)
  .filter((f) => f.endsWith(".sql"))
  .sort()
  .map((name) => ({
    name,
    sql: fs
      .readFileSync(new URL(`./migrations/${name}`, import.meta.url), "utf8")
      .replace(/^--.*$/gm, "")
      .trim(),
  }));

export default defineWorkersConfig({
  test: {
    poolOptions: {
      workers: {
        wrangler: { configPath: "./wrangler.jsonc" },
        miniflare: {
          bindings: {
            TINK_FIXTURE: JSON.stringify(fixture),
            MIGRATIONS: JSON.stringify(migrations),
          },
        },
      },
    },
  },
});

import { env } from "cloudflare:test";
