-- Phase 1 migration 0007: rate limiting + challenge authorizer
-- Fixed-window strict counters (the security-critical layer; the Workers Rate
-- Limiting binding is the soft outer layer, configured at deploy time).
CREATE TABLE rate_limits (
  bucket       TEXT NOT NULL,
  key          TEXT NOT NULL,
  window_start INTEGER NOT NULL,
  count        INTEGER NOT NULL,
  PRIMARY KEY (bucket, key)
);

-- add_device challenges are co-signed by an active device of the account;
-- the authorizer identity is stored server-side inside the challenge row.
ALTER TABLE auth_challenges ADD COLUMN authorizer_device_id TEXT REFERENCES devices(device_id);

export class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
  ) {
    super(message);
  }
}

export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json" },
  });
}

export function errorResponse(e: unknown): Response {
  if (e instanceof HttpError) {
    return jsonResponse({ error: { code: e.code, message: e.message } }, e.status);
  }
  return jsonResponse({ error: { code: "INTERNAL", message: "internal error" } }, 500);
}

export function bytesToB64(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

export function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export function bytesToHex(bytes: Uint8Array): string {
  return [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export async function sha256Hex(bytes: Uint8Array): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", bytes as BufferSource);
  return bytesToHex(new Uint8Array(digest));
}

export function randomBytes(len: number): Uint8Array {
  const out = new Uint8Array(len);
  crypto.getRandomValues(out);
  return out;
}

export function randomHex(byteLen: number): string {
  return bytesToHex(randomBytes(byteLen));
}

import { HttpError } from "./errors";
import { b64ToBytes, bytesToB64, bytesToHex, randomBytes, sha256Hex } from "./util";

export const TOKEN_TTL_MS = 30 * 60 * 1000; // 30 minutes (user-approved)

export interface AuthContext {
  device_id: string;
  account_id: string;
  dev_no: number;
  token_hash: string;
}

/** Issues a device-bound token; only SHA-256(token) is persisted. Raw 256-bit token. */
export async function issueToken(
  db: D1Database,
  deviceId: string,
  now: number,
  ttlMs = TOKEN_TTL_MS,
): Promise<{ token: string; token_expires_at: number }> {
  const raw = randomBytes(32);
  const token = bytesToB64(raw);
  const hash = await sha256Hex(raw);
  const expires_at = now + ttlMs;
  await db
    .prepare(
      "INSERT INTO auth_tokens (token_hash, device_id, issued_at, expires_at) VALUES (?1, ?2, ?3, ?4)",
    )
    .bind(hash, deviceId, now, expires_at)
    .run();
  return { token, token_expires_at: expires_at };
}

/**
 * Validates a Bearer token and resolves the device identity FROM THE TOKEN ONLY.
 * Fail-closed ordering: unknown → revoked (device or token) → expired.
 * The device row is JOINed so a revoked device invalidates all its tokens
 * even if a token row were missed.
 */
export async function authenticate(
  db: D1Database,
  authorization: string | null,
  now: number,
): Promise<AuthContext> {
  const match = authorization ? /^Bearer (.+)$/.exec(authorization) : null;
  if (!match) {
    throw new HttpError(401, "UNAUTHORIZED", "missing bearer token");
  }
  let raw: Uint8Array;
  try {
    raw = b64ToBytes(match[1]);
  } catch {
    throw new HttpError(401, "UNAUTHORIZED", "malformed token");
  }
  const hash = await sha256Hex(raw);
  const row = await db
    .prepare(
      `SELECT t.revoked_at AS token_revoked, t.expires_at AS token_expires,
              d.revoked_at AS device_revoked, d.account_id AS account_id, d.dev_no AS dev_no
       FROM auth_tokens t JOIN devices d ON d.device_id = t.device_id
       WHERE t.token_hash = ?1`,
    )
    .bind(hash)
    .first<{
      token_revoked: number | null;
      token_expires: number;
      device_revoked: number | null;
      account_id: string;
      dev_no: number;
    }>();
  if (!row) throw new HttpError(401, "UNAUTHORIZED", "invalid token");
  if (row.device_revoked !== null || row.token_revoked !== null) {
    throw new HttpError(401, "DEVICE_REVOKED", "device or token revoked");
  }
  if (row.token_expires <= now) {
    throw new HttpError(401, "TOKEN_EXPIRED", "token expired");
  }
  return {
    device_id: hash /* placeholder replaced below */,
    account_id: row.account_id,
    dev_no: row.dev_no,
    token_hash: hash,
  };
}

/** Full auth context including the real device_id (separate query keeps the JOIN lean). */
export async function authenticateFull(
  db: D1Database,
  authorization: string | null,
  now: number,
): Promise<AuthContext & { device_id: string }> {
  const match = authorization ? /^Bearer (.+)$/.exec(authorization) : null;
  if (!match) {
    throw new HttpError(401, "UNAUTHORIZED", "missing bearer token");
  }
  const raw = b64ToBytes(match[1]);
  const hash = await sha256Hex(raw);
  const tokenRow = await db
    .prepare("SELECT device_id, revoked_at, expires_at FROM auth_tokens WHERE token_hash = ?1")
    .bind(hash)
    .first<{ device_id: string; revoked_at: number | null; expires_at: number }>();
  if (!tokenRow) throw new HttpError(401, "UNAUTHORIZED", "invalid token");
  if (tokenRow.revoked_at !== null) {
    throw new HttpError(401, "DEVICE_REVOKED", "token revoked");
  }
  if (tokenRow.expires_at <= now) {
    throw new HttpError(401, "TOKEN_EXPIRED", "token expired");
  }
  const deviceRow = await db
    .prepare("SELECT account_id, dev_no, revoked_at FROM devices WHERE device_id = ?1")
    .bind(tokenRow.device_id)
    .first<{ account_id: string; dev_no: number; revoked_at: number | null }>();
  if (!deviceRow || deviceRow.revoked_at !== null) {
    throw new HttpError(401, "DEVICE_REVOKED", "device revoked");
  }
  return {
    device_id: tokenRow.device_id,
    account_id: deviceRow.account_id,
    dev_no: deviceRow.dev_no,
    token_hash: bytesToHex(raw).slice(0, 0) + hash,
  };
}

export function newTokenRaw(): Uint8Array {
  return randomBytes(32);
}

