import { handleRequest } from "./router";

interface Env {
  DB: D1Database;
  NOW_OVERRIDE_MS?: string;
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    return handleRequest(request, env);
  },
};

import { SELF, env } from "cloudflare:test";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { b64ToBytes, buildContext } from "../src/auth";

/**
 * Phase 1.3 — Authentication & Token Lifecycle (HTTP-level via SELF.fetch).
 * Covers: register flow, auth/verify flow, token binding, expiry, revocation
 * (immediate + fail-closed), cross-device/cross-account authorization,
 * idempotent/atomic challenge consumption, and initial rate limits.
 */

type Json = Record<string, any>;

const migrations = JSON.parse(
  (globalThis as Record<string, unknown>).MIGRATIONS as string,
) as { name: string; sql: string }[];

function b64(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

async function genKey(): Promise<{ priv: CryptoKey; pubB64: string }> {
  const kp = await crypto.subtle.generateKey({ name: "Ed25519" }, true, ["sign", "verify"]);
  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", kp.publicKey));
  return { priv: kp.privateKey, pubB64: b64(raw) };
}

async function signB64(priv: CryptoKey, message: string): Promise<string> {
  const sig = await crypto.subtle.sign(
    { name: "Ed25519" },
    priv,
    new TextEncoder().encode(message),
  );
  return b64(new Uint8Array(sig));
}

async function http(
  method: string,
  path: string,
  opts: { body?: Json; token?: string; ip?: string } = {},
): Promise<{ status: number; body: Json }> {
  const headers: Record<string, string> = {
    "content-type": "application/json",
    "CF-Connecting-IP": opts.ip ?? "1.2.3.4",
  };
  if (opts.token) headers["authorization"] = `Bearer ${opts.token}`;
  const res = await SELF.fetch(`https://example.com${path}`, {
    method,
    headers,
    body: opts.body ? JSON.stringify(opts.body) : undefined,
  });
  let body: Json = {};
  if (res.status !== 204) {
    try {
      body = (await res.json()) as Json;
    } catch {
      body = {};
    }
  }
  return { status: res.status, body };
}

async function issueRegisterChallenge(username: string, authPubB64: string, ip: string) {
  const identityPub = b64(crypto.getRandomValues(new Uint8Array(32)));
  return http("POST", "/auth/challenge", {
    body: { purpose: "register", username, identity_pub: identityPub, auth_pub: authPubB64 },
    ip,
  });
}

async function registerAccount(
  username: string,
  ip = "1.2.3.4",
): Promise<{ token: string; device_id: string; account_id: string; authPriv: CryptoKey }> {
  const { priv, pubB64 } = await genKey();
  const ch = await issueRegisterChallenge(username, pubB64, ip);
  expect(ch.status).toBe(200);
  const context = buildContext("register", {
    challengeId: ch.body.challenge_id,
    nonce: ch.body.nonce,
    username,
    identityPubB64: ch.body.challenge_id ? b64ToBytesToB64(identityOf(ch)) : undefined,
    authPubB64: pubB64,
  }) as string;
  // NOTE: context must mirror the server exactly; rebuild from challenge response fields.
  const ctx = buildRegisterContext(ch.body.challenge_id, ch.body.nonce, username, pubB64);
  const signature = await signB64(priv, ctx);
  const reg = await http("POST", "/accounts", {
    body: { challenge_id: ch.body.challenge_id, signature, registration_id: 1000 },
    ip,
  });
  expect(reg.status).toBe(201);
  return {
    token: reg.body.token,
    device_id: reg.body.device_id,
    account_id: reg.body.account_id,
    authPriv: priv,
  };
}

function buildRegisterContext(
  challengeId: string,
  nonce: string,
  username: string,
  authPubB64: string,
  identityPubB64 = "unknown",
): string {
  // mirrors server: v1|register|challenge_id|nonce|username|identity_pub|auth_pub
  const parts = ["v1", "register", challengeId, nonce, username, "IDENTITY_PLACEHOLDER", authPubB64];
  void identityPubB64;
  return parts.join("|");
}

function identityOf(ch: { body: Json }): Uint8Array {
  // The register challenge response does not echo identity_pub; the client knows
  // the identity key it generated. Tests use a fixed placeholder consistent with
  // the server-side stored value (server stores what the client submitted at
  // challenge time). To keep the test hermetic we re-derive it below.
  return new Uint8Array(32);
}

function b64ToBytesToB64(bytes: Uint8Array): string {
  return b64(bytes);
}

beforeAll(async () => {
  for (const m of migrations) {
    await env.DB.exec(m.sql);
  }
});

afterAll(() => {
  delete (env as Record<string, unknown>).NOW_OVERRIDE_MS;
});

import { SELF, env } from "cloudflare:test";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { buildContext } from "../src/auth";

/**
 * Phase 1.3 — Authentication & Token Lifecycle (HTTP-level via SELF.fetch).
 * Signatures in tests are produced with the official WebCrypto Ed25519 — the
 * exact primitive the Worker uses for verification.
 */

type Json = Record<string, any>;

const migrations = JSON.parse(
  (globalThis as Record<string, unknown>).MIGRATIONS as string,
) as { name: string; sql: string }[];

function b64(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

async function genKey(): Promise<{ priv: CryptoKey; pubB64: string }> {
  const kp = await crypto.subtle.generateKey({ name: "Ed25519" }, true, ["sign", "verify"]);
  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", kp.publicKey));
  return { priv: kp.privateKey, pubB64: b64(raw) };
}

async function signB64(priv: CryptoKey, message: string): Promise<string> {
  const sig = await crypto.subtle.sign({ name: "Ed25519" }, priv, new TextEncoder().encode(message));
  return b64(new Uint8Array(sig));
}

async function http(
  method: string,
  path: string,
  opts: { body?: Json; token?: string; ip?: string } = {},
): Promise<{ status: number; body: Json }> {
  const headers: Record<string, string> = {
    "content-type": "application/json",
    "CF-Connecting-IP": opts.ip ?? "1.2.3.4",
  };
  if (opts.token) headers["authorization"] = `Bearer ${opts.token}`;
  const res = await SELF.fetch(`https://example.com${path}`, {
    method,
    headers,
    body: opts.body ? JSON.stringify(opts.body) : undefined,
  });
  let body: Json = {};
  if (res.status !== 204) {
    try {
      body = (await res.json()) as Json;
    } catch {
      body = {};
    }
  }
  return { status: res.status, body };
}

function setNow(ms: number | null) {
  if (ms === null) {
    (env as Record<string, unknown>).NOW_OVERRIDE_MS = "";
  } else {
    (env as Record<string, unknown>).NOW_OVERRIDE_MS = String(ms);
  }
}

let usernameCounter = 0;
function nextUsername(prefix: string): string {
  usernameCounter += 1;
  return `${prefix}_${usernameCounter}`;
}

interface Registered {
  token: string;
  device_id: string;
  account_id: string;
  authPriv: CryptoKey;
  username: string;
}

async function registerAccount(username: string, ip: string): Promise<Registered> {
  const { priv, pubB64 } = await genKey();
  const identityPubB64 = b64(crypto.getRandomValues(new Uint8Array(32)));
  const ch = await http("POST", "/auth/challenge", {
    body: { purpose: "register", username, identity_pub: identityPubB64, auth_pub: pubB64 },
    ip,
  });
  expect(ch.status).toBe(200);
  const ctx = buildContext("register", {
    challengeId: ch.body.challenge_id,
    nonce: ch.body.nonce,
    username,
    identityPubB64,
    authPubB64: pubB64,
  });
  const signature = await signB64(priv, ctx);
  const reg = await http("POST", "/accounts", {
    body: { challenge_id: ch.body.challenge_id, signature, registration_id: 1000 },
    ip,
  });
  expect(reg.status).toBe(201);
  return {
    token: reg.body.token,
    device_id: reg.body.device_id,
    account_id: reg.body.account_id,
    authPriv: priv,
    username,
  };
}

beforeAll(async () => {
  for (const m of migrations) {
    await env.DB.exec(m.sql);
  }
});

afterAll(() => {
  setNow(null);
});

describe("registration", () => {
  it("registers an account and binds the token to its device", async () => {
    const acc = await registerAccount(nextUsername("user"), "10.0.0.1");
    const me = await http("GET", "/devices/me", { token: acc.token, ip: "10.0.0.1" });
    expect(me.status).toBe(200);
    expect(me.body.device_id).toBe(acc.device_id);
    expect(me.body.account_id).toBe(acc.account_id);
    expect(me.body.dev_no).toBe(1);
  });

  it("rejects duplicate username at challenge time", async () => {
    const username = nextUsername("dup");
    const { pubB64 } = await genKey();
    const first = await http("POST", "/auth/challenge", {
      body: {
        purpose: "register",
        username,
        identity_pub: b64(crypto.getRandomValues(new Uint8Array(32))),
        auth_pub: pubB64,
      },
      ip: "10.0.0.2",
    });
    expect(first.status).toBe(200);
    const second = await http("POST", "/auth/challenge", {
      body: {
        purpose: "register",
        username,
        identity_pub: b64(crypto.getRandomValues(new Uint8Array(32))),
        auth_pub: pubB64,
      },
      ip: "10.0.0.2",
    });
    expect(second.status).toBe(409);
    expect(second.body.error.code).toBe("USERNAME_TAKEN");
  });

  it("rejects invalid register signature and creates nothing", async () => {
    const username = nextUsername("badsig");
    const { pubB64 } = await genKey();
    const attacker = await genKey();
    const identityPubB64 = b64(crypto.getRandomValues(new Uint8Array(32)));
    const ch = await http("POST", "/auth/challenge", {
      body: { purpose: "register", username, identity_pub: identityPubB64, auth_pub: pubB64 },
      ip: "10.0.0.3",
    });
    expect(ch.status).toBe(200);
    const ctx = buildContext("register", {
      challengeId: ch.body.challenge_id,
      nonce: ch.body.nonce,
      username,
      identityPubB64,
      authPubB64: pubB64,
    });
    const wrongSig = await signB64(attacker.priv, ctx);
    const reg = await http("POST", "/accounts", {
      body: { challenge_id: ch.body.challenge_id, signature: wrongSig, registration_id: 1000 },
      ip: "10.0.0.3",
    });
    expect(reg.status).toBe(401);
    expect(reg.body.error.code).toBe("INVALID_SIGNATURE");
    // nothing was created: the username is still free
    const again = await http("POST", "/auth/challenge", {
      body: {
        purpose: "register",
        username,
        identity_pub: identityPubB64,
        auth_pub: pubB64,
      },
      ip: "10.0.0.3",
    });
    expect(again.status).toBe(200);
  });

  it("rejects an expired register challenge", async () => {
    const username = nextUsername("expired");
    const { priv, pubB64 } = await genKey();
    const identityPubB64 = b64(crypto.getRandomValues(new Uint8Array(32)));
    const ch = await issueRegisterChallenge(username, pubB64, "10.0.0.4", identityPubB64);
    expect(ch.status).toBe(200);
    setNow(Number(ch.body.expires_at) + 1);
    try {
      const ctx = buildContext("register", {
        challengeId: ch.body.challenge_id,
        nonce: ch.body.nonce,
        username,
        identityPubB64,
        authPubB64: pubB64,
      });
      const signature = await signB64(priv, ctx);
      const reg = await http("POST", "/accounts", {
        body: { challenge_id: ch.body.challenge_id, signature, registration_id: 1000 },
        ip: "10.0.0.4",
      });
      expect(reg.status).toBe(401);
      expect(reg.body.error.code).toBe("CHALLENGE_EXPIRED");
    } finally {
      setNow(null);
    }
  });
});

function issueRegisterChallenge(username: string, pubB64: string, ip: string, identityPubB64?: string) {
  return http("POST", "/auth/challenge", {
    body: {
      purpose: "register",
      username,
      identity_pub: identityPubB64 ?? b64(crypto.getRandomValues(new Uint8Array(32))),
      auth_pub: pubB64,
    },
    ip,
  });
}

