     db
       .prepare("UPDATE devices SET revoked_at = ?1 WHERE device_id = ?2 AND revoked_at IS NULL")
       .bind(now, deviceId),
     db
       .prepare("UPDATE auth_tokens SET revoked_at = ?1 WHERE device_id = ?2 AND revoked_at IS NULL")
       .bind(now, deviceId),
   ]);
